#ifndef NINTENDO_SHA256_H
#define NINTENDO_SHA256_H
#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include <string.h>
typedef struct{uint32_t h[8];uint64_t bits;unsigned char b[64];size_t n;} N_SHA;
static const uint32_t N_K[64]={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
static uint32_t nrr(uint32_t x,unsigned n){return(x>>n)|(x<<(32-n));}
static void nblock(N_SHA*s,const unsigned char*p){uint32_t w[64],a,b,c,d,e,f,g,h,t,u;int i;for(i=0;i<16;i++)w[i]=((uint32_t)p[i*4]<<24)|((uint32_t)p[i*4+1]<<16)|((uint32_t)p[i*4+2]<<8)|p[i*4+3];for(i=16;i<64;i++){uint32_t x=w[i-15],y=w[i-2];w[i]=w[i-16]+(nrr(x,7)^nrr(x,18)^(x>>3))+w[i-7]+(nrr(y,17)^nrr(y,19)^(y>>10));}a=s->h[0];b=s->h[1];c=s->h[2];d=s->h[3];e=s->h[4];f=s->h[5];g=s->h[6];h=s->h[7];for(i=0;i<64;i++){t=h+(nrr(e,6)^nrr(e,11)^nrr(e,25))+((e&f)^(~e&g))+N_K[i]+w[i];u=(nrr(a,2)^nrr(a,13)^nrr(a,22))+((a&b)^(a&c)^(b&c));h=g;g=f;f=e;e=d+t;d=c;c=b;b=a;a=t+u;}s->h[0]+=a;s->h[1]+=b;s->h[2]+=c;s->h[3]+=d;s->h[4]+=e;s->h[5]+=f;s->h[6]+=g;s->h[7]+=h;}
static void ninit(N_SHA*s){uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};memcpy(s->h,iv,sizeof iv);s->bits=0;s->n=0;}
static void nupdate(N_SHA*s,const void*vp,size_t z){const unsigned char*p=(const unsigned char*)vp;s->bits+=(uint64_t)z*8;while(z){size_t q=64-s->n;if(q>z)q=z;memcpy(s->b+s->n,p,q);s->n+=q;p+=q;z-=q;if(s->n==64){nblock(s,s->b);s->n=0;}}}
static void nfinal(N_SHA*s,unsigned char*out){uint64_t bits=s->bits;int i;s->b[s->n++]=128;if(s->n>56){while(s->n<64)s->b[s->n++]=0;nblock(s,s->b);s->n=0;}while(s->n<56)s->b[s->n++]=0;for(i=7;i>=0;i--)s->b[s->n++]=(unsigned char)(bits>>(i*8));nblock(s,s->b);for(i=0;i<8;i++){out[i*4]=s->h[i]>>24;out[i*4+1]=s->h[i]>>16;out[i*4+2]=s->h[i]>>8;out[i*4+3]=s->h[i];}}
static int nsha_file(const char*p,char*hex,uint64_t*z){FILE*f=fopen(p,"rb");unsigned char b[65536],d[32];size_t n;int i;if(!f)return 0;N_SHA s;ninit(&s);*z=0;while((n=fread(b,1,sizeof b,f))>0){nupdate(&s,b,n);*z+=n;}if(ferror(f)){fclose(f);return 0;}fclose(f);nfinal(&s,d);for(i=0;i<32;i++)sprintf(hex+2*i,"%02x",d[i]);hex[64]=0;return 1;}
#endif